"""Independent reference: Fraction-based, structurally different from main.py."""
from fractions import Fraction


def floor_log2(fr):
    # fr > 0 Fraction; return floor(log2(fr))
    a, b = fr.numerator, fr.denominator
    k = a.bit_length() - b.bit_length()
    if k >= 0:
        while a < (b << k):
            k -= 1
        while a >= (b << (k + 1)):
            k += 1
    else:
        while (a << -k) < b:
            k -= 1
        while (a << -(k + 1)) >= b:
            k += 1
    return k


def ref_solve(req):
    ebits, fbits, mode = req["ebits"], req["fbits"], req["mode"]
    pairs = req["pairs"]
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    Eall = (1 << ebits) - 1
    emin = 1 - bias
    emax = Eall - 1 - bias
    W = ebits + fbits

    def decode(h):
        v = int(h, 16)
        s = (v >> W) & 1
        e = (v >> fbits) & Eall
        f = v & (F - 1)
        if e == Eall:
            if f == 0:
                return ("inf", s)
            return ("nan", (f >> (fbits - 1)) & 1)  # (nan, quiet?)
        if e == 0:
            return ("fin", s, Fraction(f) * Fraction(2) ** (1 - bias - fbits), f == 0)
        return ("fin", s, Fraction(F + f) * Fraction(2) ** (e - bias - fbits), False)

    any_nan = False
    snan = False
    zinf = False
    inf_signs = []
    prods = []  # (sign, Fraction) finite products; value may be 0

    for ah, bh in pairs:
        A = decode(ah)
        B = decode(bh)
        for X in (A, B):
            if X[0] == "nan":
                any_nan = True

