import sys
sys.path.insert(0, "/app"); sys.path.insert(0, "/app/tests")
from main import solve
from refimpl import ref_solve

for ebits, fbits in [(3, 2), (4, 2), (3, 3)]:
    W = ebits + fbits
    N = 1 << (W + 1)
    fails = 0
    for mode in ["RNE", "RNA", "RTZ", "RUP", "RDN"]:
        for a in range(N):
            for b in range(N):
                req = {"ebits": ebits, "fbits": fbits, "mode": mode,
                       "pairs": [[format(a, "x"), format(b, "x")]]}
                g = solve(req); e = ref_solve(req)
                if int(g["bits"], 16) != int(e["bits"], 16) or set(g["flags"]) != set(e["flags"]):
                    fails += 1
                    print("MISMATCH", req, g, e)
                    if fails > 3: sys.exit(1)
    print(f"exhaustive ({ebits},{fbits}): {N*N*5} cases, {fails} failures")
EOF
